import math

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    # Validate input: there is no proper positive divisor for n <= 1
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n <= 1:
        raise ValueError("n must be greater than 1 to have a proper divisor smaller than itself")

    max_div = 1  # 1 is always a proper divisor for n > 1
    limit = math.isqrt(n)

    for i in range(2, limit + 1):
        if n % i == 0:
            other = n // i
            # both i and other are divisors; they are smaller than n (since i >= 2)
            if i > max_div:
                max_div = i
            if other > max_div and other < n:
                max_div = other

    return max_div

