def encode_cyclic(s: str):
    """
    returns encoded string by cycling groups of three characters.
    Each group of three characters is left-rotated by one position.
    Groups with fewer than three characters are left unchanged.
    """
    parts = []
    for i in range(0, len(s), 3):
        chunk = s[i:i+3]
        if len(chunk) == 3:
            parts.append(chunk[1:] + chunk[0])
        else:
            parts.append(chunk)
    return "".join(parts)


def decode_cyclic(s: str):
    """
    takes as input string encoded with encode_cyclic function. Returns decoded string.
    Reverses the encoding by right-rotating each full group of three characters by one.
    """
    parts = []
    for i in range(0, len(s), 3):
        chunk = s[i:i+3]
        if len(chunk) == 3:
            parts.append(chunk[-1] + chunk[:-1])
        else:
            parts.append(chunk)
    return "".join(parts)

