def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    if n <= 1:
        raise ValueError("n must be greater than 1")

    max_pf = None

    # Remove factor 2
    while n % 2 == 0:
        max_pf = 2
        n //= 2

    # Check odd factors
    i = 3
    while i * i <= n:
        if n % i == 0:
            max_pf = i
            while n % i == 0:
                n //= i
        else:
            i += 2

    # If remaining n is > 1, it is a prime factor larger than any found so far
    if n > 1:
        max_pf = n

    return int(max_pf)

