def exchange(lst1, lst2):
    """Determine whether it's possible to exchange elements between lst1 and lst2
    so that all elements in lst1 become even. Return "YES" or "NO".
    """
    def is_even(x):
        try:
            r = x % 2
        except Exception:
            return False
        # handle numeric types where modulo returns float (e.g., floats, numpy types)
        try:
            return abs(r) < 1e-9
        except Exception:
