import numbers

def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in the Collatz sequence.

    The Collatz sequence: start with n. If the current term is even, next = current // 2.
    If the current term is odd, next = 3 * current + 1. Sequence ends when it reaches 1.
    Return the distinct odd numbers encountered in the sequence, sorted in increasing order.

    Accepts Python integer types (including subclasses like numpy.int64). Also accepts float
    values that are whole numbers (e.g., 5.0) and will convert them to integers.
    """
    # Accept integers (including numbers.Integral like numpy ints) and whole-number floats
    if not isinstance(n, numbers.Integral):
        if isinstance(n, float) and n.is_integer():
            n = int(n)
        else:
            raise TypeError("n must be an integer")

    n = int(n)
    if n <= 0:
        raise ValueError("n must be a positive integer")

    odds = set()
    curr = n

    while True:
        if curr % 2 == 1:
            odds.add(curr)
        if curr == 1:
            break
        if curr % 2 == 0:
            curr //= 2
        else:
            curr = 3 * curr + 1

    return sorted(odds)

