from typing import List, Tuple, Set

def minPath(grid: List[List[int]], k: int) -> List[int]:
    """
    Find the lexicographically smallest sequence of values of length k
    obtainable by a walk on the grid (4-neighbor moves), starting anywhere.
    """
    n = len(grid)
    if n == 0 or k <= 0:
        return []

    # Helper: neighbors (4-directional)
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    # Find minimal value in grid and all positions that have it.
    min_val = None
    for i in range(n):
        for j in range(n):
            v = grid[i][j]
            if min_val is None or v < min_val:
                min_val = v

    result: List[int] = [min_val]
    if k == 1:
        return result

    # Current reachable positions that produce the chosen prefix (positions that
    # have the last chosen value).
    current: Set[Tuple[int,int]] = set()
    for i in range(n):
        for j in range(n):
            if grid[i][j] == min_val:
                current.add((i,j))

    # For each next step, consider all neighbors of current positions,
    # pick those with the minimal value among them, and continue.
    for _step in range(1, k):
        # Collect all neighbor positions
        neighs: Set[Tuple[int,int]] = set()
        for (i,j) in current:
            for di,dj in dirs:
                ni, nj = i+di, j+dj
                if 0 <= ni < n and 0 <= nj < n:
                    neighs.add((ni,nj))
        # Find minimal value among neighbors
        next_min = None
        for (i,j) in neighs:
            v = grid[i][j]
            if next_min is None or v < next_min:
                next_min = v

        # It's guaranteed a path exists, but guard anyway
        if next_min is None:
            break

        result.append(next_min)
        # Filter neighbors to only those with the minimal value
        current = { (i,j) for (i,j) in neighs if grid[i][j] == next_min }

    return result

