from typing import Any

def compare_one(a: Any, b: Any) -> Any:
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    def to_decimal(x: Any) -> Decimal:
        # Convert various types to Decimal while preserving decimal semantics.
        if isinstance(x, Decimal):
            return x
        if isinstance(x, int):
            return Decimal(x)
        if isinstance(x, float):
            # Use str to avoid binary float artifacts (e.g., 0.1)
            return Decimal(str(x))
        # For strings and other types, convert to string, normalize comma to dot
        s = str(x).strip().replace(',', '.')
        return Decimal(s)

    try:
        da = to_decimal(a)
        db = to_decimal(b)
    except (InvalidOperation, ValueError) as e:
        # If conversion fails, raise a clear error
        raise ValueError(f"Unable to convert inputs to numbers: {e}")

    if da == db:
        return None

    return a if da > db else b

