from typing import List, Optional

def find_max(words: List[str]) -> str:
    """Return the word with the maximum number of unique characters.
    If multiple words tie, return the lexicographically smallest one.
    If the input list is empty, return an empty string.
    """
    if not words:
        return ""

    best_word: Optional[str] = None
    max_unique = -1

    for word in words:
        uniq = len(set(word))
        if uniq > max_unique:
            max_unique = uniq
            best_word = word
        elif uniq == max_unique:
            # best_word should already be a string here
            if best_word is None or word < best_word:
                best_word = word

    return best_word if best_word is not None else ""

def do_algebra(operator, operand):
    """
    Given two lists operator, and operand. The first list has basic algebra operations, and 
    the second list is a list of integers. Use the two given lists to build the algebric 
    expression and return the evaluation of this expression.
    """
    # Build token list: operand and operator alternating
    tokens = []
    n_ops = len(operator)
    # start with first operand
    tokens.append(operand[0])
    for i in range(n_ops):
        tokens.append(operator[i])
        tokens.append(operand[i+1])

    # Define precedence and associativity
    precedence = {'+': 2, '-': 2, '*': 3, '//': 3, '**': 4}
    associativity = {'+': 'left', '-': 'left', '*': 'left', '//': 'left', '**': 'right'}

    # Shunting-yard: convert to RPN
    output_queue = []
    op_stack = []

    for tok in tokens:
        if isinstance(tok, int):
            output_queue.append(tok)
        else:
            # tok is an operator string
            while op_stack:
                top = op_stack[-1]
                # only operators are pushed onto op_stack, so top should be operator
                if top not in precedence:
                    break
                if (associativity[tok] == 'left' and precedence[tok] <= precedence[top]) or \
                   (associativity[tok] == 'right' and precedence[tok] < precedence[top]):
                    output_queue.append(op_stack.pop())
                else:
                    break
            op_stack.append(tok)

    # pop remaining operators
    while op_stack:
        output_queue.append(op_stack.pop())

    # Evaluate RPN
    stack = []
    for tok in output_queue:
        if isinstance(tok, int):
            stack.append(tok)
        else:
            # operator: pop right then left
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            elif tok == '//':
                # floor division
                res = a // b
            elif tok == '**':
                res = a ** b
            else:
                # unknown operator, though not expected
                raise ValueError(f"Unsupported operator: {tok}")
            stack.append(res)

    return stack[0]
